### Closes #271, closes #335

### Description

This PR adds support for D2D1 resource textures.

### API breakdown

```csharp
namespace ComputeSharp.D2D1
{
    [AttributeUsage(AttributeTargets.Field, AllowMultiple = false)]
    public sealed class D2DResourceTextureIndexAttribute : Attribute
    {
        public D2DResourceTextureIndexAttribute(int index);

        public int Index { get; }
    }

    public readonly struct D2D1ResourceTexture1D
    {
        public int Width { get; }

        public ref readonly Float4 this[int x] { get; }
        public ref readonly Float4 this[float u] { get; }
    }

    public readonly struct D2D1ResourceTexture2D
    {
        public int Width  { get; }
        public int Height  { get; }
        
        public ref readonly Float4 this[int x, int y] { get; }
        public ref readonly Float4 this[Int2 xy] { get; }
        public ref readonly Float4 this[float u, float v] { get; }
        public ref readonly Float4 this[Float2 uv] { get; }
    }

    public readonly struct D2D1ResourceTexture3D
    {
        public int Width { get; }
        public int Height { get; }
        public int Depth { get; }
        
        public ref readonly Float4 this[int x, int y, int z] { get; }
        public ref readonly Float4 this[Int3 xyz] { get; }        
        public ref readonly Float4 this[float u, float v, float w] { get; }
        public ref readonly Float4 this[Float3 uvw] { get; }
    }
}

namespace ComputeSharp.D2D1.Interop
{
    public static class D2D1PixelShader
    {
        public static ReadOnlyMemory<D2D1ResourceTextureDescription> GetResourceTextureDescriptions<T>()
            where T : unmanaged, ID2D1PixelShader;
    }

    public readonly struct D2D1ResourceTextureDescription
    {
        public int Index { get; }
        public int Rank { get; }
    }
}

namespace ComputeSharp.D2D1.__Internals
{
    [EditorBrowsable(EditorBrowsableState.Never)]
    [Obsolete("This interface is not intended to be used directly by user code")]
    public interface ID2D1ResourceTextureDescriptionsLoader
    {
        void LoadResourceTextureDescriptions(ReadOnlySpan<byte> data);
    }

    public interface ID2D1Shader
    {
        [EditorBrowsable(EditorBrowsableState.Never)]
        [Obsolete("This method is not intended to be used directly by user code")]
        void LoadResourceTextureDescriptions<TLoader>(ref TLoader loader)
            where TLoader : struct, ID2D1ResourceTextureDescriptionsLoader;
    }
}
```

